import re
import pytesseract
from PIL import Image, ImageOps
from collections import Counter
from openpyxl import Workbook

IMG_DIR = 'dataset/img'
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

TIERS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'],
]
EXCLUSIONS = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']
TENDER = ['CASH', 'VISA', 'MASTERCARD', 'MASTER', 'CARD', 'CREDIT', 'DEBIT', 'PAYMENT', 'PAID', 'RECEIVED', 'TENDERED', 'CHANGE']

MONEY_RE = re.compile(r'(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.])')


def canon(line):
    return re.sub(r'\s+', ' ', line.upper()).strip()


def normalize_amount_token(line):
    # Fix common OCR confusables inside numeric-ish tokens
    def fix(tok):
        if re.search(r'[0-9]', tok):
            return (tok.replace('O', '0').replace('o', '0').replace('Q', '0')
                       .replace('l', '1').replace('I', '1').replace('|', '1')
                       .replace('S', '5').replace('B', '8').replace('Z', '2'))
        return tok
    # Only fix tokens that look mostly numeric
    tokens = re.split(r'(\s+)', line)
    out = []
    for t in tokens:
        if re.match(r'^[0-9OolISBZ.,]+$', t) and re.search(r'[0-9]', t):
            out.append(fix(t))
        else:
            out.append(t)
    return ''.join(out)


def find_amount_in_line(line):
    fixed = normalize_amount_token(line)
    matches = MONEY_RE.findall(fixed)
    if matches:
        return matches[-1].replace(',', '')
    return None


def is_column_header(cline):
    header_tokens = ['DESCRIPTION', 'ITEM', 'QTY', 'U.PRICE', 'UNIT PRICE', 'PRICE', 'U/P', 'U/PRICE']
    return any(h in cline for h in header_tokens)


def extract_total(text):
    lines = [l for l in text.split('\n') if l.strip()]
    clines = [canon(l) for l in lines]

    # Detect summary section cutoff (GST SUMMARY etc.)
    cutoff = len(lines)
    for i, cl in enumerate(clines):
        if re.search(r'GST\s*SUMMARY|TAX\s*SUMMARY|SST\s*SUMMARY', cl):
            cutoff = i
            break

    for tier in TIERS:
        candidates = []
        for i in range(cutoff):
            cl = clines[i]
            if not any(k in cl for k in tier):
                continue
            if any(ex in cl for ex in EXCLUSIONS):
                continue
            if is_column_header(cl):
                continue
            candidates.append(i)
        # Iterate last to first; accept first with parseable amount
        for i in reversed(candidates):
            amt = find_amount_in_line(lines[i])
            if amt:
                return amt
            # Guarded split-line fallback: only if no digits in the keyword line
            if not re.search(r'\d', lines[i]):
                # Look at next non-empty line
                for j in range(i + 1, min(i + 3, cutoff)):
                    nl = lines[j]
                    ncl = clines[j]
                    if any(ex in ncl for ex in EXCLUSIONS):
                        continue
                    if any(t in ncl for t in TENDER):
                        continue
                    amt = find_amount_in_line(nl)
                    if amt:
                        return amt
                    break
    return None


DATE_RES = [
    # DD/MM/YYYY or DD-MM-YYYY
    re.compile(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})(?!\d)'),
    # DD/MM/YY
    re.compile(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)'),
]


def extract_date(text):
    lines = text.split('\n')
    # Prefer lines labeled DATE and not PRINT/CLOSED/LOYALTY
    priority = []
    normal = []
    for l in lines:
        cl = canon(l)
        if any(bad in cl for bad in ['PRINT', 'CLOSED', 'CLOSING', 'LOYALTY', 'PROMO', 'EXP']):
            continue
        if 'DATE' in cl or 'DATA' in cl or 'DAIE' in cl:
            priority.append(l)
        else:
            normal.append(l)

    for group in (priority, normal):
        for l in group:
            for rx in DATE_RES:
                m = rx.search(l)
                if m:
                    d, mo, y = m.groups()
                    d, mo = int(d), int(mo)
                    y = int(y)
                    if y < 100:
                        y += 2000
                    # Assume DD/MM; validate
                    if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
                        return f'{y:04d}-{mo:02d}-{d:02d}'
                    # Try MM/DD
                    if 1 <= mo <= 31 and 1 <= d <= 12 and 2000 <= y <= 2099:
                        return f'{y:04d}-{d:02d}-{mo:02d}'
    return None


def ocr_variants(path):
    img = Image.open(path)
    gray = ImageOps.grayscale(img)
    variants = []
    # Base
    variants.append(pytesseract.image_to_string(img))
    for scale in [2, 3]:
        big = gray.resize((gray.size[0]*scale, gray.size[1]*scale))
        auto = ImageOps.autocontrast(big)
        for psm in [6, 4]:
            variants.append(pytesseract.image_to_string(auto, config=f'--psm {psm}'))
    return variants


def extract_file(path):
    variants = ocr_variants(path)
    totals = []
    dates = []
    for v in variants:
        t = extract_total(v)
        if t:
            totals.append(t)
        d = extract_date(v)
        if d:
            dates.append(d)
    total = Counter(totals).most_common(1)[0][0] if totals else None
    date = Counter(dates).most_common(1)[0][0] if dates else None
    return date, total


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    rows = []
    for f in files:
        d, t = extract_file(os.path.join(IMG_DIR, f))
        if t is not None:
            # Normalize to two decimals
            t = f'{float(t):.2f}'
        rows.append((f, d, t))
        print(f, d, t)

    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for f, d, t in rows:
        ws.append([f, d, t])
    wb.save(OUT_PATH)
    print('Saved to', OUT_PATH)


if __name__ == '__main__':
    main()
